import sys
from math import gcd

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    M = next(it)
    S = [next(it) for _ in range(N)]

    size = 1
    while size < N:
        size <<= 1

    EMPTY = (0, [], [], 0, 0)
    tree = [EMPTY] * (2 * size)

    for i in range(N):
        v = S[i]
        ans = 1 if v > 1 else 0
        tree[size + i] = (ans, [(v, 1)], [(v, 1)], v, 1)

    def combine(A, B):
        if A[4] == 0:
            return B
        if B[4] == 0:
            return A
        ansA, prefA, suffA, gA, lenA = A
        ansB, prefB, suffB, gB, lenB = B

        new_g = gcd(gA, gB)
        new_len = lenA + lenB

        if new_g > 1:
            new_ans = new_len * (new_len + 1) // 2
        else:
            j = len(prefB) - 1
            current_sum = lenB
            cross = 0
            for gA_s, cA in suffA:
                while j >= 0 and gcd(gA_s, prefB[j][0]) <= 1:
                    current_sum -= prefB[j][1]
                    j -= 1
                if j < 0:
                    break
                cross += cA * current_sum
            new_ans = ansA + ansB + cross

        if gA == 1:
            new_pref = list(prefA)
            last_g, last_c = new_pref[-1]
            new_pref[-1] = (last_g, last_c + lenB)
        else:
            new_pref = list(prefA)
            for g, c in prefB:
                ng = gcd(gA, g)
                if new_pref and new_pref[-1][0] == ng:
                    last_g, last_c = new_pref[-1]
                    new_pref[-1] = (last_g, last_c + c)
                else:
                    new_pref.append((ng, c))

        if gB == 1:
            new_suff = list(suffB)
            last_g, last_c = new_suff[-1]
            new_suff[-1] = (last_g, last_c + lenA)
        else:
            new_suff = list(suffB)
            for g, c in suffA:
                ng = gcd(g, gB)
                if new_suff and new_suff[-1][0] == ng:
                    last_g, last_c = new_suff[-1]
                    new_suff[-1] = (last_g, last_c + c)
                else:
                    new_suff.append((ng, c))

        return (new_ans, new_pref, new_suff, new_g, new_len)

    for i in range(size - 1, 0, -1):
        tree[i] = combine(tree[2*i], tree[2*i+1])

    out = []
    for _ in range(M):
        T = next(it)
        if T == 1:
            I = next(it)
            V = next(it)
            idx = size + I - 1
            v = V
            ans = 1 if v > 1 else 0
            tree[idx] = (ans, [(v, 1)], [(v, 1)], v, 1)
            idx //= 2
            while idx >= 1:
                tree[idx] = combine(tree[2*idx], tree[2*idx+1])
                idx //= 2
        else:
            E = next(it)
            D = next(it)
            l = size + E - 1
            r = size + D
            left_res = EMPTY
            right_res = EMPTY
            while l < r:
                if l & 1:
                    left_res = combine(left_res, tree[l])
                    l += 1
                if r & 1:
                    r -= 1
                    right_res = combine(tree[r], right_res)
                l //= 2
                r //= 2
            res = combine(left_res, right_res)
            out.append(str(res[0]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
